@namespace Lumeo
@inject Lumeo.Services.Localization.ILumeoLocalizer L
@inject Lumeo.Services.IComponentInteropService Interop
@inject Microsoft.Extensions.Options.IOptions<Lumeo.Services.LumeoGestureOptions> GestureOpts
@implements IAsyncDisposable

<div data-slot="calendar" class="@CssClass" @attributes="AdditionalAttributes">
    @if (NumberOfMonths == 1)
    {
        @RenderMonth(DisplayDate)
    }
    else
    {
        <div class="flex gap-4">
            @for (var i = 0; i < NumberOfMonths; i++)
            {
                var monthDate = AddMonths(DisplayDate, i);
                <div>
                    @RenderMonth(monthDate, showPrev: i == 0, showNext: i == NumberOfMonths - 1)
                </div>
            }
        </div>
    }
</div>

@code {
    /// <summary>The selected day in single-selection mode. Ignored when <see cref="IsRange"/> or <see cref="IsMultiple"/> is set. Pair with <see cref="ValueChanged"/> for two-way binding.</summary>
    [Parameter] public DateOnly? Value { get; set; }

    /// <summary>Raised after a day is selected in single-selection mode.</summary>
    [Parameter] public EventCallback<DateOnly?> ValueChanged { get; set; }

    /// <summary>Earliest selectable day. Days before it render disabled and the "previous month" navigation stops at the containing month.</summary>
    [Parameter] public DateOnly? MinDate { get; set; }

    /// <summary>Latest selectable day. Days after it render disabled and the "next month" navigation stops at the containing month.</summary>
    [Parameter] public DateOnly? MaxDate { get; set; }

    /// <summary>When true, the grid selects a start/end range instead of a single day. Takes precedence over <see cref="Value"/> selection.</summary>
    [Parameter] public bool IsRange { get; set; }

    /// <summary>The range's start day in range-selection mode. Pair with <see cref="RangeStartChanged"/> for two-way binding.</summary>
    [Parameter] public DateOnly? RangeStart { get; set; }

    /// <summary>Raised when the range's start day changes.</summary>
    [Parameter] public EventCallback<DateOnly?> RangeStartChanged { get; set; }

    /// <summary>The range's end day in range-selection mode. Pair with <see cref="RangeEndChanged"/> for two-way binding.</summary>
    [Parameter] public DateOnly? RangeEnd { get; set; }

    /// <summary>Raised when the range's end day changes.</summary>
    [Parameter] public EventCallback<DateOnly?> RangeEndChanged { get; set; }
    /// <summary>When true the grid selects a set of independent days: clicking a
    /// day (or Enter/Space on it) toggles it in/out of <see cref="Values"/>.
    /// Takes precedence over single <see cref="Value"/> selection; ignored when
    /// <see cref="IsRange"/> is set.</summary>
    [Parameter] public bool IsMultiple { get; set; }
    /// <summary>The selected days in multiple-selection mode. Pair with
    /// <see cref="ValuesChanged"/> for two-way binding.</summary>
    [Parameter] public List<DateOnly>? Values { get; set; }
    /// <summary>Raised when the selected set changes in multiple-selection mode (<see cref="IsMultiple"/>).</summary>
    [Parameter] public EventCallback<List<DateOnly>?> ValuesChanged { get; set; }

    /// <summary>Number of month panels rendered side by side. Defaults to <c>1</c>.</summary>
    [Parameter] public int NumberOfMonths { get; set; } = 1;

    /// <summary>When true, adds a leading column showing each row's ISO week number. Default is <c>false</c>.</summary>
    [Parameter] public bool ShowWeekNumbers { get; set; }

    /// <summary>Convenience shortcut that opens the calendar straight into the year-picker view, overriding <see cref="InitialView"/>. Default is <c>false</c>.</summary>
    [Parameter] public bool ShowYearPicker { get; set; }

    /// <summary>The view (days/months/years) the calendar first renders. Defaults to <see cref="CalendarView.Days"/>; overridden by <see cref="ShowYearPicker"/>.</summary>
    [Parameter] public CalendarView InitialView { get; set; } = CalendarView.Days;

    /// <summary>Predicate that marks individual dates as non-selectable, in addition to the <see cref="MinDate"/>/<see cref="MaxDate"/> bounds.</summary>
    [Parameter] public Func<DateTime, bool>? IsDateDisabled { get; set; }

    /// <summary>Returns extra CSS classes to append to a specific day's button, e.g. to highlight holidays or booked dates.</summary>
    [Parameter] public Func<DateTime, string>? DateClass { get; set; }
    /// <summary>Optional per-date tooltip text. Returned string is shown via the
    /// styled Lumeo <c>&lt;Tooltip&gt;</c> on hover/focus (not the native browser
    /// <c>title</c> attribute). Return <c>null</c> or empty for no tooltip on
    /// that date. Useful for booking calendars: "Booked by John, 14:00–17:00"
    /// or "Sold out".</summary>
    [Parameter] public Func<DateTime, string?>? DateTooltip { get; set; }
    /// <summary>Optional per-date indicator slot. Returns a <c>RenderFragment</c>
    /// rendered absolutely positioned in the bottom-right of the day cell —
    /// good for status dots, count badges, icons. Return <c>null</c> for no
    /// badge on that date. The slot is non-interactive
    /// (<c>pointer-events-none</c>) so clicks still hit the day button.</summary>
    [Parameter] public Func<DateTime, RenderFragment?>? DateBadge { get; set; }
    /// <summary>The day of the week to render in the leftmost column.
    /// When <c>null</c> (default), uses
    /// <c>CultureInfo.CurrentCulture.DateTimeFormat.FirstDayOfWeek</c> —
    /// so de-DE / fr-FR / etc. start on Monday automatically, en-US on
    /// Sunday. With <see cref="CalendarSystem"/> set to
    /// <see cref="Lumeo.CalendarSystem.Jalali"/> the default is Saturday instead.
    /// Pass an explicit <see cref="DayOfWeek"/> to override.</summary>
    [Parameter] public DayOfWeek? FirstDayOfWeek { get; set; }
    /// <summary>When <c>true</c> (default), users can swipe left/right on the
    /// day grid to navigate to the next or previous month on touch devices.
    /// Vertical page scroll is unaffected (<c>touch-action: pan-y</c>).
    /// Set to <c>false</c> to disable swipe navigation.</summary>
    [Parameter] public bool SwipeEnabled { get; set; } = true;
    /// <summary>The calendar system the month grid, headers and navigation follow.
    /// <see cref="Lumeo.CalendarSystem.Jalali"/> renders Solar Hijri (Persian) months
    /// — and starts the week on Saturday unless <see cref="FirstDayOfWeek"/> is set —
    /// while <see cref="Value"/>, <see cref="MinDate"/> etc. stay plain Gregorian
    /// <see cref="DateOnly"/> values. Under a <c>fa</c> culture Jalali month names and
    /// numbers render in Persian; otherwise Latin transliterations and ASCII digits are
    /// used. Default <see cref="Lumeo.CalendarSystem.Gregorian"/>.</summary>
    [Parameter] public CalendarSystem CalendarSystem { get; set; } = CalendarSystem.Gregorian;

    private readonly string _elementId = LumeoIds.New("cal-grid");

    private DayOfWeek EffectiveFirstDayOfWeek =>
        FirstDayOfWeek ?? CalendarSystemMath.DefaultFirstDayOfWeek(CalendarSystem, System.Globalization.CultureInfo.CurrentCulture);

    // Calendar-system aware helpers. Gregorian maps straight onto DateOnly.
    private DateOnly MonthStart(DateOnly date) => CalendarSystemMath.MonthStart(CalendarSystem, date);
    private DateOnly MonthStart(int year, int month) => CalendarSystemMath.MonthStart(CalendarSystem, year, month);
    private DateOnly AddMonths(DateOnly date, int months) => CalendarSystemMath.AddMonths(CalendarSystem, date, months);
    private bool SameMonth(DateOnly a, DateOnly b) => CalendarSystemMath.SameMonth(CalendarSystem, a, b);
    private int YearOf(DateOnly date) => CalendarSystemMath.GetYear(CalendarSystem, date);
    private int MonthOf(DateOnly date) => CalendarSystemMath.GetMonth(CalendarSystem, date);
    private string Num(int value) => CalendarSystemMath.FormatNumber(CalendarSystem, value, System.Globalization.CultureInfo.CurrentCulture);
    private string MonthTitle(DateOnly monthDate) => CalendarSystemMath.MonthTitle(CalendarSystem, monthDate, System.Globalization.CultureInfo.CurrentCulture);
    /// <summary>Additional CSS classes merged onto the root element.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes are splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private DateOnly DisplayDate { get; set; }
    private DateOnly? _hoverDate;
    private CalendarView _currentView = CalendarView.Days;
    private bool _swipeAttached;
    // Roving-tabindex focus target for keyboard grid navigation (WAI-ARIA grid
    // pattern). Exactly one day button is tabbable (tabindex=0) — the focused
    // day — every other day carries tabindex=-1. Lazily seeded from the
    // selected/today/first-of-month day so the initial Tab lands somewhere sane.
    private DateOnly? _focusedDate;
    // Tracks the id the prevent-default-keys listener was registered against so
    // we can re-register when the day-grid element id changes and unregister on
    // dispose (mirrors TreeViewNode's page-scroll suppression).
    private string? _pdRegisteredId;
    // Last-seen bound anchor (Value, or RangeStart in range mode). Used to
    // detect *external* value changes in OnParametersSet without stomping the
    // user's manual month navigation on unrelated re-renders.
    private DateOnly? _lastSeenAnchor;

    private string CssClass => Cx.Merge("p-[var(--lumeo-calendar-p,calc(var(--spacing,0.25rem)*3))]", Class);

    protected override void OnInitialized()
    {
        // ShowYearPicker is a convenience shortcut that opens straight into the
        // year-picker view. When set it wins over InitialView so consumers can
        // request the year grid without knowing the CalendarView enum.
        _currentView = ShowYearPicker ? CalendarView.Years : InitialView;
        // CurrentAnchor folds in multiple/range/single precedence so the
        // displayed month seeds correctly regardless of selection mode.
        _lastSeenAnchor = CurrentAnchor;
        DisplayDate = MonthStart(_lastSeenAnchor ?? DateOnly.FromDateTime(DateTime.Today));
    }

    private CalendarSystem? _lastCalendarSystem;

    protected override void OnParametersSet()
    {
        // A CalendarSystem switch on a live calendar re-anchors the displayed month to
        // the first day of a month in the NEW system; otherwise the panels would render
        // from a mid-month date and keyboard focus could target a panel id that no
        // longer exists.
        if (_lastCalendarSystem.HasValue && _lastCalendarSystem != CalendarSystem)
            DisplayDate = MonthStart(DisplayDate);
        _lastCalendarSystem = CalendarSystem;

        // When the bound anchor (Value, RangeStart, or the first selected day in
        // multiple mode) changes from outside — e.g. the parent sets it
        // programmatically on an inline calendar — navigate the visible month to
        // it. Only react to actual changes: re-renders that leave the anchor
        // untouched must not reset manual browsing.
        //
        // Only treat a *non-null* anchor as a change worth tracking/navigating to.
        // An async load flicker (June15 → null → June15) must be a no-op: nulling
        // _lastSeenAnchor on the transient clear would make the refill look like a
        // brand-new external value and yank the user's browsed month back to the
        // anchor. By never overwriting _lastSeenAnchor with null, the eventual
        // refill equals the retained value and no navigation fires.
        var anchor = CurrentAnchor;
        if (anchor.HasValue && anchor != _lastSeenAnchor)
        {
            _lastSeenAnchor = anchor;
            DisplayDate = MonthStart(anchor.Value);
            // Realign the roving-tabindex target to the new anchor. Without this,
            // an external Value change *within the displayed month* (June15 →
            // June20) leaves DisplayDate untouched, so EnsureFocusedDate — which
            // only re-seeds when _focusedDate falls OUT of the window — keeps the
            // tabbable day on the stale date. Gated on a real anchor change so it
            // never clobbers an in-progress keyboard navigation on an unrelated
            // re-render (those don't change the anchor and so don't reach here).
            _focusedDate = anchor;
        }
    }

    // The day the displayed month tracks for external value changes: in
    // multiple mode the earliest selected day, in range mode the start, else
    // the single Value.
    private DateOnly? CurrentAnchor =>
        IsMultiple ? (Values is { Count: > 0 } ? Values.Min() : null)
        : IsRange ? RangeStart
        : Value;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // The id-bearing day grid element exists only for a single-month Days
        // view (the gridId in RenderMonth is null for multi-month panels, which
        // share one component, and for the Months/Years pickers). Both the swipe
        // handler and the page-scroll suppression for the keyboard-nav keys
        // attach to that element, so they must (un)register as the grid appears
        // and disappears — including a NumberOfMonths 1→2→1 round-trip. An early
        // `if (NumberOfMonths != 1) return;` here would skip teardown on the way
        // out and re-registration on the way back, permanently orphaning both.
        var hasSingleGrid = NumberOfMonths == 1 && _currentView == CalendarView.Days;

        if (hasSingleGrid && SwipeEnabled && !_swipeAttached)
        {
            _swipeAttached = true;
            try { await Interop.RegisterHorizontalSwipe(_elementId, OnSwipeAsync, GestureOpts.Value.SwipeThresholdPx, GestureOpts.Value.VerticalDeadZonePx); }
            catch (JSDisconnectedException) { _swipeAttached = false; }
            catch (InvalidOperationException) { _swipeAttached = false; } // JS unavailable during prerender
        }
        else if ((!hasSingleGrid || !SwipeEnabled) && _swipeAttached)
        {
            _swipeAttached = false;
            try { await Interop.UnregisterHorizontalSwipe(_elementId); }
            catch (JSDisconnectedException) { }
        }

        // Suppress page scroll for the arrow / Home / End / PageUp / PageDown
        // keys while the day grid is visible — without this the first keypress
        // scrolls the page as focus also moves (same pattern as TreeViewNode).
        if (hasSingleGrid && _pdRegisteredId != _elementId)
        {
            try
            {
                await Interop.RegisterPreventDefaultKeys(_elementId, NavKeyRules);
                _pdRegisteredId = _elementId;
            }
            catch (JSDisconnectedException) { }
            catch (InvalidOperationException) { } // JS unavailable during prerender
        }
        else if (!hasSingleGrid && _pdRegisteredId is not null)
        {
            try { await Interop.UnregisterPreventDefaultKeys(_pdRegisteredId); }
            catch (JSDisconnectedException) { }
            _pdRegisteredId = null;
        }
    }

    // Keys whose browser default (page scroll) is suppressed on the day grid.
    private static readonly PreventDefaultKeyRule[] NavKeyRules =
    [
        new("ArrowLeft"), new("ArrowRight"), new("ArrowUp"), new("ArrowDown"),
        new("Home"), new("End"), new("PageUp"), new("PageDown"),
    ];

    private Task OnSwipeAsync(string direction)
    {
        if (_currentView != CalendarView.Days) return Task.CompletedTask;
        if (direction == "next" && !IsNextMonthDisabled)
            NextMonth();
        else if (direction == "prev" && !IsPrevMonthDisabled)
            PreviousMonth();
        StateHasChanged();
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        if (_swipeAttached)
        {
            try { await Interop.UnregisterHorizontalSwipe(_elementId); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
        if (_pdRegisteredId is not null)
        {
            try { await Interop.UnregisterPreventDefaultKeys(_pdRegisteredId); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
    }

    private bool IsPrevMonthDisabled =>
        MinDate.HasValue && MonthStart(DisplayDate) <= MonthStart(MinDate.Value);

    private bool IsNextMonthDisabled
    {
        get
        {
            var lastPanel = AddMonths(DisplayDate, NumberOfMonths - 1);
            return MaxDate.HasValue && MonthStart(lastPanel) >= MonthStart(MaxDate.Value);
        }
    }

    private bool IsDisabled(DateOnly day) =>
        (MinDate.HasValue && day < MinDate.Value) || (MaxDate.HasValue && day > MaxDate.Value)
        || (IsDateDisabled != null && IsDateDisabled(day.ToDateTime(TimeOnly.MinValue)));

    private string[] GetDayHeaders()
    {
        // .NET's ShortestDayNames collapses to 1 letter per culture
        // ("S,M,T,W,T,F,S"), which is ambiguous in any language. Use
        // AbbreviatedDayNames and take the first two letters of each so we
        // get culture-correct, distinguishable headers:
        //   en-US → Su/Mo/Tu/We/Th/Fr/Sa
        //   de-DE → So/Mo/Di/Mi/Do/Fr/Sa
        //   fr-FR → di/lu/ma/me/je/ve/sa
        var abbr = System.Globalization.CultureInfo.CurrentCulture.DateTimeFormat.AbbreviatedDayNames;
        var startIndex = (int)EffectiveFirstDayOfWeek;
        var result = new string[7];
        for (var i = 0; i < 7; i++)
        {
            var raw = abbr[(startIndex + i) % 7];
            // Strip trailing punctuation (de-DE returns "So.", "Mo." …) before slicing.
            var letters = new string(raw.TakeWhile(char.IsLetter).ToArray());
            result[i] = letters.Length >= 2 ? letters[..2] : letters;
        }
        return result;
    }

    private List<DateOnly> GetCalendarDays(DateOnly monthDate)
    {
        var days = new List<DateOnly>();
        var firstOfMonth = MonthStart(monthDate);
        var startOffset = ((int)firstOfMonth.DayOfWeek - (int)EffectiveFirstDayOfWeek + 7) % 7;
        var start = firstOfMonth.AddDays(-startOffset);

        for (var i = 0; i < 42; i++)
        {
            days.Add(start.AddDays(i));
        }
        return days;
    }

    private int GetIsoWeekNumber(DateOnly date)
    {
        var dt = date.ToDateTime(TimeOnly.MinValue);
        var day = System.Globalization.CultureInfo.InvariantCulture.Calendar.GetDayOfWeek(dt);
        if (day >= DayOfWeek.Monday && day <= DayOfWeek.Wednesday)
        {
            dt = dt.AddDays(3);
        }
        return System.Globalization.CultureInfo.InvariantCulture.Calendar.GetWeekOfYear(dt,
            System.Globalization.CalendarWeekRule.FirstFourDayWeek, DayOfWeek.Monday);
    }

    private int GetDecadeStart(int year) => year / 10 * 10;

    // Wrapper-div classes that render the connecting range bar BEHIND the
    // day button (2.1.4). Previously each in-range day's button had its own
    // rounded-md bg-accent rectangle, producing a pearl-necklace look with
    // visual gaps between days. The wrapper carries the bar background and
    // edge rounding so adjacent in-range cells touch seamlessly.
    //
    // Returns empty string for non-Range mode or days outside the range so
    // the wrapper has no styling and the button keeps its original look.
    //
    // Edge cases:
    // - First column on a row (col == 0) gets rounded-s-md so the bar starts
    //   with a rounded cap when the range wraps to a new row.
    // - Last column on a row (col == 6) gets rounded-e-md likewise.
    // - The range-start and range-end days get rounded-s-md / rounded-e-md
    //   so the bar terminates with a soft cap behind the primary circle.
    // - Hover during in-flight selection (RangeStart set, RangeEnd null,
    //   _hoverDate carries the preview) extends the bar dynamically.
    private string RangeBarClasses(DateOnly day, DateOnly monthDate, int col)
    {
        if (!IsRange) return "";

        var effectiveEnd = RangeEnd ?? (RangeStart.HasValue && _hoverDate.HasValue ? _hoverDate : null);
        var rangeFrom = RangeStart;
        var rangeTo = effectiveEnd;
        if (rangeFrom.HasValue && rangeTo.HasValue && rangeTo < rangeFrom)
        {
            (rangeFrom, rangeTo) = (rangeTo, rangeFrom);
        }
        if (!rangeFrom.HasValue || !rangeTo.HasValue) return "";
        if (day < rangeFrom.Value || day > rangeTo.Value) return "";

        var isStart = day == rangeFrom.Value;
        var isEnd = day == rangeTo.Value;

        // flex layout keeps the button (h-8 w-8) centered horizontally so the
        // surrounding bar extends to the cell edges on either side.
        var parts = new List<string> { "flex items-center justify-center bg-accent" };
        if (isStart || col == 0) parts.Add("rounded-s-md");
        if (isEnd || col == 6) parts.Add("rounded-e-md");
        return string.Join(" ", parts);
    }

    // The day-cell button, rendered either bare or as the AsChild trigger of a Lumeo
    // <Tooltip> (when DateTooltip yields a hint). slotAttrs carries aria-describedby
    // (only while the tooltip is open) so the button itself is described on focus.
    private RenderFragment RenderDay(DateOnly d, DateOnly monthDate, RenderFragment? badge, IReadOnlyDictionary<string, object>? slotAttrs) =>
        @<button type="button" id="@DayId(monthDate, d)" tabindex="@DayTabIndex(d, monthDate)"
                 aria-label="@DayAriaLabel(d)"
                 aria-pressed="@(IsMultiple ? ((Values?.Contains(d) ?? false) ? "true" : "false") : null)"
                 class="@DayClasses(d, monthDate)" disabled="@IsDisabled(d)"
                 @attributes="slotAttrs"
                 @onclick="() => SelectDay(d)" @onmouseenter="() => OnDayHover(d)"
                 @onfocus="() => OnDayFocus(d)"
                 @onkeydown="e => HandleDayKeyDownAsync(e, monthDate, d)">
            @Num(CalendarSystemMath.GetDay(CalendarSystem, d))
            @if (badge is not null)
            {
                <span class="absolute -bottom-0.5 -end-0.5 pointer-events-none flex">@badge</span>
            }
        </button>;

    private string DayClasses(DateOnly day, DateOnly monthDate)
    {
        var isCurrentMonth = SameMonth(day, monthDate);
        var isDisabled = IsDisabled(day);
        var isSelected = IsMultiple
            ? (Values?.Contains(day) ?? false)
            : (!IsRange && Value.HasValue && day == Value.Value);
        var isToday = day == DateOnly.FromDateTime(DateTime.Today);

        // 'relative' kept on every day so DateBadge slots can absolute-position inside.
        var baseClass = "relative inline-flex items-center justify-center rounded-md h-[var(--lumeo-calendar-cell-size,calc(var(--spacing,0.25rem)*8))] w-[var(--lumeo-calendar-cell-size,calc(var(--spacing,0.25rem)*8))] text-sm transition-colors focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1";
        var extraClass = DateClass != null ? DateClass(day.ToDateTime(TimeOnly.MinValue)) : "";

        if (isDisabled)
            return $"{baseClass} pointer-events-none opacity-50 {extraClass}".Trim();

        if (IsRange)
        {
            var isRangeStart = RangeStart.HasValue && day == RangeStart.Value;
            var isRangeEnd = RangeEnd.HasValue && day == RangeEnd.Value;

            var effectiveEnd = RangeEnd ?? (RangeStart.HasValue && _hoverDate.HasValue ? _hoverDate : null);
            var rangeFrom = RangeStart;
            var rangeTo = effectiveEnd;
            if (rangeFrom.HasValue && rangeTo.HasValue && rangeTo < rangeFrom)
            {
                (rangeFrom, rangeTo) = (rangeTo, rangeFrom);
            }

            var inRange = rangeFrom.HasValue && rangeTo.HasValue && day > rangeFrom.Value && day < rangeTo.Value;

            if (isRangeStart || isRangeEnd)
                return $"{baseClass} bg-primary text-primary-foreground font-medium {extraClass}".Trim();
            if (inRange)
                return $"{baseClass} bg-accent text-accent-foreground {extraClass}".Trim();
            if (isToday)
                return $"{baseClass} bg-accent text-accent-foreground font-medium {extraClass}".Trim();
            if (!isCurrentMonth)
                return $"{baseClass} text-muted-foreground/50 hover:bg-accent hover:text-accent-foreground {extraClass}".Trim();
            return $"{baseClass} hover:bg-accent hover:text-accent-foreground {extraClass}".Trim();
        }

        if (isSelected)
            return $"{baseClass} bg-primary text-primary-foreground font-medium {extraClass}".Trim();
        if (isToday)
            return $"{baseClass} bg-accent text-accent-foreground font-medium {extraClass}".Trim();
        if (!isCurrentMonth)
            return $"{baseClass} text-muted-foreground/50 hover:bg-accent hover:text-accent-foreground {extraClass}".Trim();
        return $"{baseClass} hover:bg-accent hover:text-accent-foreground {extraClass}".Trim();
    }

    private async Task SelectDay(DateOnly day)
    {
        if (IsDisabled(day)) return;

        // Keep the roving-tabindex target on the just-selected day so it stays
        // the tabbable cell (and keyboard focus stays put after Enter/Space).
        _focusedDate = day;

        if (IsMultiple)
        {
            // Toggle the day in/out of the selected set; keep the result sorted
            // so consumers get a stable, chronological list.
            var next = Values is null ? new List<DateOnly>() : new List<DateOnly>(Values);
            if (!next.Remove(day)) next.Add(day);
            next.Sort();
            Values = next;
            DisplayDate = MonthStart(day);
            // Keep the external-change tracker aligned with this internal mutation,
            // exactly like the single-Value branch below. CurrentAnchor in multiple
            // mode is the earliest selected day (Values.Min()); without this, toggling
            // OFF the earliest day shifts the Min(), and the parent's echo of the same
            // list reads as a new external anchor in OnParametersSet and teleports the
            // displayed month away from where the user just clicked.
            _lastSeenAnchor = next.Count > 0 ? next.Min() : null;
            await ValuesChanged.InvokeAsync(next);
            return;
        }

        if (IsRange)
        {
            // In range mode CurrentAnchor => RangeStart. Track the resulting start
            // so the parent's echo of the same RangeStart is recognized as unchanged
            // in OnParametersSet (otherwise a range edit that moves the start could
            // teleport the displayed month on the round-trip), mirroring the
            // single-Value branch below.
            DateOnly newRangeStart;
            if (!RangeStart.HasValue || (RangeStart.HasValue && RangeEnd.HasValue))
            {
                await RangeStartChanged.InvokeAsync(day);
                await RangeEndChanged.InvokeAsync(null);
                _hoverDate = null;
                newRangeStart = day;
            }
            else
            {
                var start = RangeStart.Value;
                if (day < start)
                {
                    await RangeStartChanged.InvokeAsync(day);
                    await RangeEndChanged.InvokeAsync(start);
                    newRangeStart = day;
                }
                else
                {
                    await RangeEndChanged.InvokeAsync(day);
                    newRangeStart = start;
                }
                _hoverDate = null;
            }
            DisplayDate = MonthStart(day);
            _lastSeenAnchor = newRangeStart;
        }
        else
        {
            DisplayDate = MonthStart(day);
            Value = day;
            // Keep the external-change tracker aligned with this internal
            // mutation so an unrelated parent re-render later (uncontrolled
            // usage) doesn't read it as a new external value and yank the
            // display month away from wherever the user has browsed to.
            _lastSeenAnchor = day;
            await ValueChanged.InvokeAsync(day);
        }
    }

    private void OnDayHover(DateOnly day)
    {
        if (IsRange && RangeStart.HasValue && !RangeEnd.HasValue)
        {
            _hoverDate = day;
        }
    }

    // ---- WAI-ARIA grid keyboard navigation (roving tabindex) ----

    /// <summary>Whether <paramref name="day"/> renders as the selected day —
    /// drives <c>aria-selected</c> on the grid cell. In multiple mode every day
    /// in <see cref="Values"/> is selected; in range mode the two endpoints are
    /// the selected cells; otherwise the single <see cref="Value"/>.</summary>
    private bool IsDaySelected(DateOnly day) => IsMultiple
        ? (Values?.Contains(day) ?? false)
        : IsRange
            ? (RangeStart.HasValue && day == RangeStart.Value) || (RangeEnd.HasValue && day == RangeEnd.Value)
            : Value.HasValue && day == Value.Value;

    /// <summary>Deterministic per-day element id used as the keyboard focus
    /// target. Scoped to the rendered month panel so the same calendar date
    /// appearing as a trailing/leading day in another panel gets a distinct id.</summary>
    private string DayId(DateOnly monthDate, DateOnly day)
        => $"{_elementId}-{monthDate.Year:D4}{monthDate.Month:D2}-{day:yyyyMMdd}";

    /// <summary>Full, culture-localized date for the day button's
    /// <c>aria-label</c> (e.g. "Saturday, June 14, 2025"). Uses the same
    /// CurrentCulture the month/day headers are formatted with.</summary>
    private string DayAriaLabel(DateOnly day)
        => CalendarSystemMath.LongDate(CalendarSystem, day, System.Globalization.CultureInfo.CurrentCulture);

    /// <summary>The window of months currently on screen. Keyboard focus must
    /// land on a day that belongs to one of these months' own days.</summary>
    private DateOnly FirstDisplayedMonth => MonthStart(DisplayDate);
    private DateOnly LastDisplayedMonthEnd =>
        CalendarSystemMath.MonthEnd(CalendarSystem, AddMonths(DisplayDate, NumberOfMonths - 1));

    /// <summary>Lazily seeds the roving-tabindex target and keeps it inside the
    /// displayed month window. Preference order: the selected day, then today,
    /// then the first of the displayed month — so the first Tab into the grid
    /// lands somewhere meaningful.</summary>
    private void EnsureFocusedDate()
    {
        bool InWindow(DateOnly d) => d >= FirstDisplayedMonth && d <= LastDisplayedMonthEnd;

        if (_focusedDate is { } f && InWindow(f)) return;

        var preferred = IsRange ? (RangeEnd ?? RangeStart) : Value;
        var today = DateOnly.FromDateTime(DateTime.Today);
        var seed =
            preferred is { } p && InWindow(p) ? p :
            InWindow(today) ? today :
            FirstDisplayedMonth;

        // The tabbable day must be interactive (a native-disabled button can't
        // be Tab-focused), so nudge the seed forward to the first enabled day in
        // the window when the natural choice is disabled.
        if (IsDisabled(seed))
            seed = SkipDisabled(seed, 1);
        _focusedDate = seed;
    }

    /// <summary>Roving tabindex: exactly one day button — the focused day, shown
    /// as a current-month cell — is in the tab sequence; every other day carries
    /// -1 and is reached with the arrow keys. The current-month guard keeps the
    /// count at one even though leading/trailing days repeat the date.</summary>
    private string DayTabIndex(DateOnly day, DateOnly monthDate)
    {
        EnsureFocusedDate();
        return day == _focusedDate && SameMonth(day, monthDate) ? "0" : "-1";
    }

    /// <summary>Keeps the roving tabindex aligned when a day receives DOM focus
    /// directly (mouse click or Tab) rather than via arrow-key navigation.</summary>
    private void OnDayFocus(DateOnly day)
    {
        if (_focusedDate != day)
            _focusedDate = day;
    }

    /// <summary>WAI-ARIA grid navigation. Arrow keys move one day (±1) or one
    /// week (±7); Home/End jump to the start/end of the focused week;
    /// PageUp/PageDown change month; Enter/Space select the focused day.
    /// Moving across a month boundary navigates the displayed month and keeps
    /// focus on the correct day.</summary>
    private async Task HandleDayKeyDownAsync(KeyboardEventArgs e, DateOnly monthDate, DateOnly day)
    {
        // Only the tabbable (current-month) cell drives navigation, so repeated
        // leading/trailing copies of the same date don't double-handle the key.
        if (day != _focusedDate || !SameMonth(day, monthDate)) return;

        switch (e.Key)
        {
            // Directional keys move first, then skip over disabled days (mouse
            // can't select them either) so focus never lands on a non-interactive
            // native-disabled button. SkipDisabled starts at the moved date and
            // continues in the same direction.
            case "ArrowLeft":  await MoveFocusToAsync(SkipDisabled(day.AddDays(-1), -1)); break;
            case "ArrowRight": await MoveFocusToAsync(SkipDisabled(day.AddDays(1), 1)); break;
            case "ArrowUp":    await MoveFocusToAsync(SkipDisabled(day.AddDays(-7), -1)); break;
            case "ArrowDown":  await MoveFocusToAsync(SkipDisabled(day.AddDays(7), 1)); break;
            case "Home":       await MoveFocusToAsync(SkipDisabled(StartOfWeek(day), 1)); break;
            case "End":        await MoveFocusToAsync(SkipDisabled(StartOfWeek(day).AddDays(6), -1)); break;
            case "PageUp":     await MoveFocusToAsync(SkipDisabled(AddMonths(day, -1), 1)); break;
            case "PageDown":   await MoveFocusToAsync(SkipDisabled(AddMonths(day, 1), -1)); break;
            // Enter/Space are intentionally NOT handled here: the day cell is a
            // native <button> whose @onclick already calls SelectDay, so handling
            // the key here too fired SelectDay twice — in range mode that set
            // RangeStart and RangeEnd to the same day in a single keypress.
        }
    }

    /// <summary>Returns the first non-disabled day at or beyond <paramref name="from"/>
    /// stepping by <paramref name="step"/> days. Bounded so a fully-disabled run
    /// (or hitting Min/MaxDate) settles rather than looping; if everything in
    /// range is disabled it falls back to the original day (selection there is a
    /// no-op anyway, matching the mouse).</summary>
    private DateOnly SkipDisabled(DateOnly from, int step)
    {
        var candidate = from;
        for (var i = 0; i < 62 && IsDisabled(candidate); i++)
        {
            // AddDays THROWS (it does not clamp) once the result would leave DateOnly's
            // 0001-01-01..9999-12-31 range, so stop there. Min/MaxDate constraints
            // normally settle this loop long before the type bounds are reached.
            DateOnly next;
            try { next = candidate.AddDays(step); }
            catch (ArgumentOutOfRangeException) { break; }
            candidate = next;
        }
        return IsDisabled(candidate) ? from : candidate;
    }

    private DateOnly StartOfWeek(DateOnly day)
    {
        var offset = ((int)day.DayOfWeek - (int)EffectiveFirstDayOfWeek + 7) % 7;
        return day.AddDays(-offset);
    }

    /// <summary>Moves the roving focus to <paramref name="target"/>, navigating
    /// the displayed month if the target falls outside the current window, then
    /// pushes DOM focus onto the target day button via JS interop.</summary>
    private async Task MoveFocusToAsync(DateOnly target)
    {
        // No enabled day in the requested direction (whole run disabled, or the
        // clamp at Min/MaxDate landed on a disabled day): keep focus put so the
        // tabbable day never becomes a non-focusable native-disabled button.
        if (IsDisabled(target)) return;

        _focusedDate = target;

        // Pull the displayed month onto the target so the day actually renders
        // as a current-month cell (the tabbable one) in some visible panel.
        if (target < FirstDisplayedMonth || target > LastDisplayedMonthEnd)
            DisplayDate = MonthStart(target);

        StateHasChanged();

        // The day's home-month panel owns the tabbable copy. With a single month
        // that's DisplayDate; with several it's the panel whose month matches.
        var ownerMonth = NumberOfMonths == 1
            ? DisplayDate
            : MonthStart(target);
        try { await Interop.FocusElement(DayId(ownerMonth, target)); }
        catch (JSDisconnectedException) { }
    }

    private void PreviousMonth() => DisplayDate = MonthStart(AddMonths(DisplayDate, -1));
    private void NextMonth() => DisplayDate = MonthStart(AddMonths(DisplayDate, 1));

    private void SwitchToMonthView() => _currentView = CalendarView.Months;
    private void SwitchToYearView() => _currentView = CalendarView.Years;

    private void SelectMonth(int month)
    {
        DisplayDate = MonthStart(YearOf(DisplayDate), month);
        _currentView = CalendarView.Days;
    }

    private void SelectYear(int year)
    {
        DisplayDate = MonthStart(year, MonthOf(DisplayDate));
        _currentView = CalendarView.Months;
    }

    private void PreviousDecade()
    {
        var decadeStart = GetDecadeStart(YearOf(DisplayDate));
        DisplayDate = MonthStart(Math.Max(CalendarSystemMath.MinYear(CalendarSystem), decadeStart - 10), MonthOf(DisplayDate));
    }

    private void NextDecade()
    {
        var decadeStart = GetDecadeStart(YearOf(DisplayDate));
        DisplayDate = MonthStart(Math.Min(CalendarSystemMath.MaxYear(CalendarSystem), decadeStart + 10), MonthOf(DisplayDate));
    }

    private void PreviousYear()
    {
        DisplayDate = MonthStart(Math.Max(CalendarSystemMath.MinYear(CalendarSystem), YearOf(DisplayDate) - 1), MonthOf(DisplayDate));
    }

    private void NextYear()
    {
        DisplayDate = MonthStart(Math.Min(CalendarSystemMath.MaxYear(CalendarSystem), YearOf(DisplayDate) + 1), MonthOf(DisplayDate));
    }

    private RenderFragment RenderMonth(DateOnly monthDate, bool showPrev = true, bool showNext = true) => __builder =>
    {
        @* The content width is seven day cells (7 × --lumeo-calendar-cell-size, 224px by
           default; eight with the week-number column), so the Days, Months and Years views
           all render at the same outer width.
           Without this the Months / Years 3-col grid (w-full cells) would collapse
           to its natural width and the picker would visibly resize between views. *@
        <div class="@(ShowWeekNumbers ? "w-[calc(var(--lumeo-calendar-cell-size,calc(var(--spacing,0.25rem)*8))*8)]" : "w-[calc(var(--lumeo-calendar-cell-size,calc(var(--spacing,0.25rem)*8))*7)]") flex flex-col">
        <div class="flex items-center justify-between px-1 mb-2">
            @if (showPrev)
            {
                if (_currentView == CalendarView.Years)
                {
                    <button type="button" aria-label="@L["Calendar.PrevYear"]" class="inline-flex items-center justify-center rounded-md h-11 w-11 sm:h-7 sm:w-7 hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1" @onclick="PreviousDecade">
                        <SvgGlyph Svg="@(LumeoIcons.ChevronLeft)" class="h-4 w-4" />
                    </button>
                }
                else if (_currentView == CalendarView.Months)
                {
                    <button type="button" aria-label="@L["Calendar.PrevYear"]" class="inline-flex items-center justify-center rounded-md h-11 w-11 sm:h-7 sm:w-7 hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1" @onclick="PreviousYear">
                        <SvgGlyph Svg="@(LumeoIcons.ChevronLeft)" class="h-4 w-4" />
                    </button>
                }
                else
                {
                    <button type="button" aria-label="@L["Calendar.PrevMonth"]" class="inline-flex items-center justify-center rounded-md h-11 w-11 sm:h-7 sm:w-7 hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1 disabled:pointer-events-none disabled:opacity-30" disabled="@IsPrevMonthDisabled" @onclick="PreviousMonth">
                        <SvgGlyph Svg="@(LumeoIcons.ChevronLeft)" class="h-4 w-4" />
                    </button>
                }
            }
            else
            {
                <div class="w-11 sm:w-7"></div>
            }

            @if (_currentView == CalendarView.Years)
            {
                var decadeStart = GetDecadeStart(YearOf(monthDate));
                <span class="text-sm font-medium">@Num(decadeStart) - @Num(decadeStart + 9)</span>
            }
            else if (_currentView == CalendarView.Months)
            {
                <button type="button" class="text-sm font-medium hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1 rounded-md px-2 py-1" @onclick="SwitchToYearView">
                    @Num(YearOf(monthDate))
                </button>
            }
            else
            {
                @* Single combined click target: 1st click → Months view, 2nd click
                   (now in Months view, on the year header) → Years view. Cleaner
                   than two adjacent buttons that look identical but route to
                   different pickers. *@
                <button type="button" class="text-sm font-medium hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1 rounded-md px-2 py-1" @onclick="SwitchToMonthView">
                    @MonthTitle(monthDate)
                </button>
            }

            @if (showNext)
            {
                if (_currentView == CalendarView.Years)
                {
                    <button type="button" aria-label="@L["Calendar.NextYear"]" class="inline-flex items-center justify-center rounded-md h-11 w-11 sm:h-7 sm:w-7 hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1" @onclick="NextDecade">
                        <SvgGlyph Svg="@(LumeoIcons.ChevronRight)" class="h-4 w-4" />
                    </button>
                }
                else if (_currentView == CalendarView.Months)
                {
                    <button type="button" aria-label="@L["Calendar.NextYear"]" class="inline-flex items-center justify-center rounded-md h-11 w-11 sm:h-7 sm:w-7 hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1" @onclick="NextYear">
                        <SvgGlyph Svg="@(LumeoIcons.ChevronRight)" class="h-4 w-4" />
                    </button>
                }
                else
                {
                    <button type="button" aria-label="@L["Calendar.NextMonth"]" class="inline-flex items-center justify-center rounded-md h-11 w-11 sm:h-7 sm:w-7 hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1 disabled:pointer-events-none disabled:opacity-30" disabled="@IsNextMonthDisabled" @onclick="NextMonth">
                        <SvgGlyph Svg="@(LumeoIcons.ChevronRight)" class="h-4 w-4" />
                    </button>
                }
            }
            else
            {
                <div class="w-11 sm:w-7"></div>
            }
        </div>

        @if (_currentView == CalendarView.Years)
        {
            var decadeStart = GetDecadeStart(YearOf(monthDate));
            var todayYear = YearOf(DateOnly.FromDateTime(DateTime.Today));
            <div class="grid grid-cols-3 gap-2 p-1">
                @for (var y = decadeStart; y < decadeStart + 12; y++)
                {
                    var year = y;
                    var isCurrentYear = year == todayYear;
                    var isSelectedYear = year == YearOf(monthDate);
                    var yearClass = isSelectedYear
                        ? "inline-flex items-center justify-center rounded-md h-9 w-full text-sm font-medium bg-primary text-primary-foreground"
                        : isCurrentYear
                            ? "inline-flex items-center justify-center rounded-md h-9 w-full text-sm font-medium bg-accent text-accent-foreground"
                            : "inline-flex items-center justify-center rounded-md h-9 w-full text-sm hover:bg-accent hover:text-accent-foreground cursor-pointer focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1";
                    <button type="button" class="@yearClass" @onclick="() => SelectYear(year)">@Num(year)</button>
                }
            </div>
        }
        else if (_currentView == CalendarView.Months)
        {
            var today = DateOnly.FromDateTime(DateTime.Today);
            <div class="grid grid-cols-3 gap-2 p-1">
                @for (var m = 1; m <= 12; m++)
                {
                    var month = m;
                    var isCurrentMonth = month == MonthOf(today) && YearOf(monthDate) == YearOf(today);
                    var isSelectedMonth = month == MonthOf(monthDate);
                    var monthClass = isSelectedMonth
                        ? "inline-flex items-center justify-center rounded-md h-9 w-full text-sm font-medium bg-primary text-primary-foreground"
                        : isCurrentMonth
                            ? "inline-flex items-center justify-center rounded-md h-9 w-full text-sm font-medium bg-accent text-accent-foreground"
                            : "inline-flex items-center justify-center rounded-md h-9 w-full text-sm hover:bg-accent hover:text-accent-foreground cursor-pointer focus-visible:outline-none focus-visible:ring-[1.5px] focus-visible:ring-ring focus-visible:ring-offset-1";
                    <button type="button" class="@monthClass" @onclick="() => SelectMonth(month)">@CalendarSystemMath.MonthName(CalendarSystem, month, System.Globalization.CultureInfo.CurrentCulture, abbreviated: true)</button>
                }
            </div>
        }
        else
        {
            var gridCols = ShowWeekNumbers ? "grid-cols-8" : "grid-cols-7";
            // Single-month grids carry the per-instance id so JS can attach swipe
            // and the page-scroll suppression for the keyboard nav keys. Multi-
            // month panels share one component so the id is omitted there to
            // avoid duplicate-id collisions (keyboard focus still works — each
            // day button has its own deterministic id).
            var gridId = NumberOfMonths == 1 ? _elementId : null;
            @* role="grid" + role="row"/role="gridcell" give the day grid proper
               table semantics for assistive tech. The week rows use the `contents`
               display so the flat CSS grid layout (and ShowWeekNumbers column) is
               unchanged — the row wrappers add no box, only ARIA structure. *@
            <div id="@gridId" role="grid" aria-label="@MonthTitle(monthDate)" class="grid @gridCols gap-0 text-center">
                <div role="row" class="contents">
                    @if (ShowWeekNumbers)
                    {
                        <div role="columnheader" class="text-xs font-medium text-muted-foreground py-1">#</div>
                    }
                    @foreach (var day in GetDayHeaders())
                    {
                        <div role="columnheader" class="text-xs font-medium text-muted-foreground py-1">@day</div>
                    }
                </div>

                @{ var calDays = GetCalendarDays(monthDate); }
                @for (var row = 0; row < 6; row++)
                {
                    var weekRow = row;
                    <div role="row" class="contents">
                        @if (ShowWeekNumbers)
                        {
                            var weekDate = calDays[weekRow * 7];
                            <div role="rowheader" class="inline-flex items-center justify-center h-[var(--lumeo-calendar-cell-size,calc(var(--spacing,0.25rem)*8))] w-[var(--lumeo-calendar-cell-size,calc(var(--spacing,0.25rem)*8))] text-xs text-muted-foreground">@Num(GetIsoWeekNumber(weekDate))</div>
                        }
                        @for (var col = 0; col < 7; col++)
                        {
                            var d = calDays[weekRow * 7 + col];
                            var dt = d.ToDateTime(TimeOnly.MinValue);
                            var tooltip = DateTooltip?.Invoke(dt);
                            var badge = DateBadge?.Invoke(dt);
                            var isSelectedDay = IsDaySelected(d);
                            <div role="gridcell" aria-selected="@isSelectedDay.ToString().ToLowerInvariant()" class="@RangeBarClasses(d, monthDate, col)">
                                @if (tooltip is not null)
                                {
                                    @* DateTooltip dogfoods the Lumeo <Tooltip> (styled, accessible) instead of
                                       the native title. AsChild keeps aria-describedby on the day button; the
                                       wrapper is forced to `block w-full` so the full-width grid cell is preserved
                                       (the Tooltip root is inline-flex by default, which would shrink the day).
                                       Content is lazy (only mounts on hover) so 42 cells stay cheap. *@
                                    <Tooltip Class="block w-full">
                                        <TooltipTrigger AsChild>
                                            <ChildContentSlot Context="slot">@RenderDay(d, monthDate, badge, slot.Attributes)</ChildContentSlot>
                                        </TooltipTrigger>
                                        <TooltipContent>@tooltip</TooltipContent>
                                    </Tooltip>
                                }
                                else
                                {
                                    @RenderDay(d, monthDate, badge, null)
                                }
                            </div>
                        }
                    </div>
                }
            </div>
        }
        </div> @* close the fixed-width wrapper *@
    };

    public enum CalendarView
    {
        Days,
        Months,
        Years
    }

}

using System.Globalization;
using System.Text;

namespace Lumeo;

/// <summary>
/// The calendar system a <see cref="Calendar"/> / <see cref="DatePicker"/> lays its
/// months out in. The bound values are always plain <see cref="DateOnly"/> (Gregorian)
/// dates — only the month grid, headers, navigation and display text follow the
/// selected system.
/// </summary>
public enum CalendarSystem
{
    /// <summary>The Gregorian calendar (default).</summary>
    Gregorian,

    /// <summary>The Solar Hijri / Jalali (Persian) calendar, backed by
    /// <see cref="PersianCalendar"/>. Weeks start on Saturday unless
    /// <c>FirstDayOfWeek</c> is set explicitly.</summary>
    Jalali,
}

/// <summary>
/// Calendar-system aware date math and formatting shared by <see cref="Calendar"/>
/// and <see cref="DatePicker"/>. Gregorian goes straight through <see cref="DateOnly"/>
/// so the default path behaves exactly as before; Jalali converts through a
/// <see cref="PersianCalendar"/> (its members are read-only, so one shared instance is safe).
/// </summary>
internal static class CalendarSystemMath
{
    private static readonly PersianCalendar Persian = new();

    private static readonly DateOnly PersianMin = DateOnly.FromDateTime(Persian.MinSupportedDateTime);
    private static readonly DateOnly PersianMax = DateOnly.FromDateTime(Persian.MaxSupportedDateTime);

    private static readonly string[] JalaliMonthNamesFa =
    [
        "فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
        "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند",
    ];

    private static readonly string[] JalaliMonthNamesLatin =
    [
        "Farvardin", "Ordibehesht", "Khordad", "Tir", "Mordad", "Shahrivar",
        "Mehr", "Aban", "Azar", "Dey", "Bahman", "Esfand",
    ];

    private static readonly string[] JalaliMonthNamesLatinAbbr =
    [
        "Far", "Ord", "Kho", "Tir", "Mor", "Sha",
        "Meh", "Aba", "Aza", "Dey", "Bah", "Esf",
    ];

    private static readonly int[] MonthsByNameLength = Enumerable.Range(1, 12)
        .OrderByDescending(m => Math.Max(JalaliMonthNamesFa[m - 1].Length, JalaliMonthNamesLatin[m - 1].Length))
        .ToArray();

    /// <summary>Default display/parse pattern for Jalali dates when no <c>Format</c> is given.</summary>
    public const string JalaliDefaultFormat = "yyyy/MM/dd";

    private static DateTime ToPersianDateTime(DateOnly date)
    {
        if (date < PersianMin) date = PersianMin;
        else if (date > PersianMax) date = PersianMax;
        return date.ToDateTime(TimeOnly.MinValue);
    }

    public static int GetYear(CalendarSystem system, DateOnly date) =>
        system == CalendarSystem.Jalali ? Persian.GetYear(ToPersianDateTime(date)) : date.Year;

    public static int GetMonth(CalendarSystem system, DateOnly date) =>
        system == CalendarSystem.Jalali ? Persian.GetMonth(ToPersianDateTime(date)) : date.Month;

    public static int GetDay(CalendarSystem system, DateOnly date) =>
        system == CalendarSystem.Jalali ? Persian.GetDayOfMonth(ToPersianDateTime(date)) : date.Day;

    public static int MinYear(CalendarSystem system) =>
        system == CalendarSystem.Jalali ? GetYear(system, PersianMin) : 1;

    public static int MaxYear(CalendarSystem system) =>
        system == CalendarSystem.Jalali ? GetYear(system, PersianMax) : 9999;

    /// <summary>Builds the first day of <paramref name="month"/>/<paramref name="year"/>,
    /// clamped into the range the calendar system supports.</summary>
    public static DateOnly MonthStart(CalendarSystem system, int year, int month)
    {
        if (system != CalendarSystem.Jalali)
            return new DateOnly(Math.Clamp(year, 1, 9999), Math.Clamp(month, 1, 12), 1);

        year = Math.Clamp(year, MinYear(system), MaxYear(system));
        month = Math.Clamp(month, 1, 12);
        if (year == MaxYear(system))
            month = Math.Min(month, GetMonth(system, PersianMax));
        return DateOnly.FromDateTime(Persian.ToDateTime(year, month, 1, 0, 0, 0, 0));
    }

    /// <summary>The first day of the month <paramref name="date"/> falls in.</summary>
    public static DateOnly MonthStart(CalendarSystem system, DateOnly date) =>
        system == CalendarSystem.Jalali
            ? MonthStart(system, GetYear(system, date), GetMonth(system, date))
            : new DateOnly(date.Year, date.Month, 1);

    /// <summary>The last day of the month <paramref name="date"/> falls in.</summary>
    public static DateOnly MonthEnd(CalendarSystem system, DateOnly date)
    {
        if (system != CalendarSystem.Jalali)
            return new DateOnly(date.Year, date.Month, DateTime.DaysInMonth(date.Year, date.Month));

        var start = MonthStart(system, date);
        var days = Persian.GetDaysInMonth(GetYear(system, start), GetMonth(system, start));
        var end = start.AddDays(days - 1);
        return end > PersianMax ? PersianMax : end;
    }

    /// <summary>Adds whole months in the calendar system, clamping the day of month
    /// (e.g. 31 Shahrivar + 1 month → 30 Mehr) like <see cref="DateOnly.AddMonths"/>.</summary>
    public static DateOnly AddMonths(CalendarSystem system, DateOnly date, int months)
    {
        if (system != CalendarSystem.Jalali)
            return date.AddMonths(months);

        try
        {
            return DateOnly.FromDateTime(Persian.AddMonths(ToPersianDateTime(date), months));
        }
        catch (ArgumentException)
        {
            return months < 0 ? PersianMin : PersianMax;
        }
    }

    public static bool SameMonth(CalendarSystem system, DateOnly a, DateOnly b) =>
        system == CalendarSystem.Jalali
            ? GetYear(system, a) == GetYear(system, b) && GetMonth(system, a) == GetMonth(system, b)
            : a.Year == b.Year && a.Month == b.Month;

    /// <summary>Jalali weeks conventionally start on Saturday; Gregorian follows the culture.</summary>
    public static DayOfWeek DefaultFirstDayOfWeek(CalendarSystem system, CultureInfo culture) =>
        system == CalendarSystem.Jalali ? DayOfWeek.Saturday : culture.DateTimeFormat.FirstDayOfWeek;

    private static bool IsPersianCulture(CultureInfo culture) =>
        culture.TwoLetterISOLanguageName is "fa";

    public static string MonthName(CalendarSystem system, int month, CultureInfo culture, bool abbreviated = false)
    {
        if (system != CalendarSystem.Jalali)
        {
            return abbreviated
                ? culture.DateTimeFormat.AbbreviatedMonthNames[month - 1]
                : culture.DateTimeFormat.MonthNames[month - 1];
        }

        if (IsPersianCulture(culture)) return JalaliMonthNamesFa[month - 1];
        return abbreviated ? JalaliMonthNamesLatinAbbr[month - 1] : JalaliMonthNamesLatin[month - 1];
    }

    /// <summary>Formats a number for display. Jalali dates under a Persian (<c>fa</c>)
    /// culture use Persian digits (۰–۹); everything else uses ASCII digits.</summary>
    public static string FormatNumber(CalendarSystem system, int value, CultureInfo culture, int minDigits = 1)
    {
        var text = value.ToString("D" + minDigits, CultureInfo.InvariantCulture);
        if (system != CalendarSystem.Jalali || !IsPersianCulture(culture)) return text;

        var sb = new StringBuilder(text.Length);
        foreach (var ch in text)
            sb.Append(ch is >= '0' and <= '9' ? (char)('۰' + (ch - '0')) : ch);
        return sb.ToString();
    }

    /// <summary>"Mehr 1403" / "مهر ۱۴۰۳" style month heading.</summary>
    public static string MonthTitle(CalendarSystem system, DateOnly date, CultureInfo culture)
    {
        if (system != CalendarSystem.Jalali)
            return date.ToString("MMMM yyyy", culture);

        return $"{MonthName(system, GetMonth(system, date), culture)} {FormatNumber(system, GetYear(system, date), culture)}";
    }

    /// <summary>Full, screen-reader friendly date ("Saturday, 12 Mehr 1403").</summary>
    public static string LongDate(CalendarSystem system, DateOnly date, CultureInfo culture)
    {
        if (system != CalendarSystem.Jalali)
            return date.ToDateTime(TimeOnly.MinValue).ToString("D", culture);

        return Format(system, date, "dddd, d MMMM yyyy", culture);
    }

    /// <summary>
    /// Formats <paramref name="date"/> with a .NET-style custom date pattern. For Gregorian
    /// this is plain <see cref="DateOnly.ToString(string, IFormatProvider)"/>. For Jalali the
    /// day/month/year tokens (<c>d dd ddd dddd M MM MMM MMMM y yy yyyy</c>) are resolved
    /// against the Persian calendar; quoted text and every other character is kept as-is.
    /// </summary>
    public static string Format(CalendarSystem system, DateOnly date, string pattern, CultureInfo culture)
    {
        if (system != CalendarSystem.Jalali)
            return date.ToString(pattern, culture);

        pattern = ExpandStandardFormat(pattern);
        var year = GetYear(system, date);
        var month = GetMonth(system, date);
        var day = GetDay(system, date);
        var sb = new StringBuilder();

        for (var i = 0; i < pattern.Length; i++)
        {
            var ch = pattern[i];
            if (ch is '\'' or '"')
            {
                var close = pattern.IndexOf(ch, i + 1);
                if (close < 0) close = pattern.Length;
                sb.Append(pattern, i + 1, close - i - 1);
                i = close;
                continue;
            }
            if (ch == '\\' && i + 1 < pattern.Length)
            {
                sb.Append(pattern[++i]);
                continue;
            }
            if (ch is not ('y' or 'M' or 'd'))
            {
                sb.Append(ch);
                continue;
            }

            var run = 1;
            while (i + run < pattern.Length && pattern[i + run] == ch) run++;
            i += run - 1;

            switch (ch)
            {
                case 'y':
                    sb.Append(run <= 2
                        ? FormatNumber(system, year % 100, culture, run)
                        : FormatNumber(system, year, culture, run));
                    break;
                case 'M':
                    sb.Append(run switch
                    {
                        1 => FormatNumber(system, month, culture),
                        2 => FormatNumber(system, month, culture, 2),
                        3 => MonthName(system, month, culture, abbreviated: true),
                        _ => MonthName(system, month, culture),
                    });
                    break;
                default: // 'd'
                    var dow = (int)date.DayOfWeek;
                    sb.Append(run switch
                    {
                        1 => FormatNumber(system, day, culture),
                        2 => FormatNumber(system, day, culture, 2),
                        3 => culture.DateTimeFormat.AbbreviatedDayNames[dow],
                        _ => culture.DateTimeFormat.DayNames[dow],
                    });
                    break;
            }
        }

        return sb.ToString();
    }

    /// <summary>Maps the single-letter .NET standard date formats (<c>d D M m Y y</c>) to
    /// equivalent custom patterns for the Jalali formatter; anything else passes through.</summary>
    private static string ExpandStandardFormat(string pattern) => pattern switch
    {
        "d" => JalaliDefaultFormat,
        "D" => "dddd, d MMMM yyyy",
        "M" or "m" => "d MMMM",
        "Y" or "y" => "MMMM yyyy",
        _ => pattern,
    };

    /// <summary>
    /// Parses user-typed Jalali text against <paramref name="pattern"/>. Accepts ASCII,
    /// Persian and Arabic-Indic digits and any separators; the order of the numeric
    /// year/month/day parts follows the pattern (default <c>yyyy/MM/dd</c>). A textual
    /// month (Persian or Latin transliteration) is recognised when the pattern uses
    /// <c>MMM</c>/<c>MMMM</c>.
    /// </summary>
    public static bool TryParseJalali(string text, string pattern, out DateOnly result)
    {
        result = default;
        if (string.IsNullOrWhiteSpace(text)) return false;

        pattern = ExpandStandardFormat(pattern);

        // First pass: walk the pattern token by token, so the picker's own output
        // ("yyyyMd", "yyyyMM/dd", "yyyy/MM/dd '14'", "MMMM yyyy", ...) always parses back.
        if (TryParsePositional(ToAsciiDigits(text.Trim()), pattern, out result)) return true;

        // Second pass: lenient extraction for hand-typed variations ("1403-7-12", "۱۴۰۳/۷/۱۲").
        var order = TokenOrder(pattern, out var widths, out var literals); // e.g. "yMd", widths {4,2,2}
        var ascii = ToAsciiDigits(text.Trim());
        // Quoted pattern literals ("'v2' yyyy/MM/dd") may contain digits: drop them first.
        foreach (var literal in literals)
        {
            var lit = ToAsciiDigits(literal);
            var at = lit.Length > 0 ? ascii.IndexOf(lit, StringComparison.OrdinalIgnoreCase) : -1;
            if (at >= 0) ascii = ascii.Remove(at, lit.Length).Insert(at, " ");
        }
        var runs = ExtractNumberRuns(ascii);
        var numbers = runs.Select(x => x.Value).ToList();
        var lengths = runs.Select(x => x.Length).ToList();

        // Separator-less patterns such as "yyyyMMdd" format to one digit run
        // ("14030712"): split it back by the pattern's token widths.
        if (numbers.Count <= 1 && order.Length == 3 && widths.Sum() == DigitCount(ascii))
        {
            var digits = new string(ascii.Where(c => c is >= '0' and <= '9').ToArray());
            numbers = new List<int>(3);
            lengths = new List<int>(widths);
            var pos = 0;
            foreach (var w in widths)
            {
                numbers.Add(int.Parse(digits.AsSpan(pos, w), NumberStyles.None, CultureInfo.InvariantCulture));
                pos += w;
            }
        }

        int year, month, day, yearLength;
        var textualMonth = FindMonthName(ascii);

        if (textualMonth > 0 && numbers.Count == 2)
        {
            var numericOrder = order.Replace("M", "");
            if (numericOrder.Length != 2) numericOrder = "dy";
            year = numbers[numericOrder.IndexOf('y')];
            yearLength = lengths[numericOrder.IndexOf('y')];
            day = numbers[numericOrder.IndexOf('d')];
            month = textualMonth;
        }
        else if (numbers.Count == 3)
        {
            if (order.Length != 3) order = "yMd";
            year = numbers[order.IndexOf('y')];
            yearLength = lengths[order.IndexOf('y')];
            month = numbers[order.IndexOf('M')];
            day = numbers[order.IndexOf('d')];
        }
        else
        {
            return false;
        }

        // Only a year typed with at most two digits is abbreviated: it resolves through the
        // calendar's TwoDigitYearMax window (99 → 1399, 03 → 1403). "0001" stays year 1.
        if (yearLength <= 2) year = Persian.ToFourDigitYear(year);
        return TryCreate(year, month, day, out result);
    }

    private enum PatternTokenKind { Literal, Year, Month, MonthName, Day, DayName }

    private readonly record struct PatternToken(PatternTokenKind Kind, int Width, string Text);

    private static List<PatternToken> Tokenize(string pattern)
    {
        var tokens = new List<PatternToken>();
        for (var i = 0; i < pattern.Length; i++)
        {
            var ch = pattern[i];
            if (ch is '\'' or '"')
            {
                var close = pattern.IndexOf(ch, i + 1);
                if (close < 0) close = pattern.Length;
                tokens.Add(new(PatternTokenKind.Literal, 0, pattern.Substring(i + 1, close - i - 1)));
                i = close;
                continue;
            }
            if (ch == '\\' && i + 1 < pattern.Length)
            {
                tokens.Add(new(PatternTokenKind.Literal, 0, pattern[++i].ToString()));
                continue;
            }
            if (ch is not ('y' or 'M' or 'd'))
            {
                tokens.Add(new(PatternTokenKind.Literal, 0, ch.ToString()));
                continue;
            }
            var run = 1;
            while (i + run < pattern.Length && pattern[i + run] == ch) run++;
            i += run - 1;
            tokens.Add(ch switch
            {
                'y' => new(PatternTokenKind.Year, run, ""),
                'M' => new(run >= 3 ? PatternTokenKind.MonthName : PatternTokenKind.Month, run, ""),
                _ => new(run >= 3 ? PatternTokenKind.DayName : PatternTokenKind.Day, run, ""),
            });
        }
        return tokens;
    }

    private static bool IsNumeric(PatternTokenKind kind) =>
        kind is PatternTokenKind.Year or PatternTokenKind.Month or PatternTokenKind.Day;

    /// <summary>
    /// Matches <paramref name="ascii"/> against the pattern position by position. Literals
    /// must appear where the pattern puts them; a numeric field directly followed by another
    /// numeric field takes its pattern width (1–2 digits for single-letter <c>M</c>/<c>d</c>),
    /// otherwise the whole digit run. Every valid split is tried and the parse succeeds only
    /// when exactly one distinct date results, so an ambiguous split fails instead of
    /// guessing. Fields the pattern omits default to day 1 / the current Jalali year.
    /// </summary>
    private static bool TryParsePositional(string ascii, string pattern, out DateOnly result)
    {
        result = default;
        var tokens = Tokenize(pattern);
        if (!tokens.Any(t => t.Kind is PatternTokenKind.Year or PatternTokenKind.Month
                or PatternTokenKind.MonthName or PatternTokenKind.Day))
            return false;

        var found = new HashSet<DateOnly>();
        Walk(0, 0, null, 0, null, null);
        if (found.Count != 1) return false;
        result = found.First();
        return true;

        void Walk(int ti, int pos, int? year, int yearLen, int? month, int? day)
        {
            if (found.Count > 1) return;
            if (ti == tokens.Count)
            {
                if (!ascii.AsSpan(pos).IsWhiteSpace()) return;
                var y = year ?? GetYear(CalendarSystem.Jalali, DateOnly.FromDateTime(DateTime.Today));
                if (year.HasValue && yearLen <= 2) y = Persian.ToFourDigitYear(y);
                if (TryCreate(y, month ?? 1, day ?? 1, out var d)) found.Add(d);
                return;
            }

            var t = tokens[ti];
            switch (t.Kind)
            {
                case PatternTokenKind.Literal:
                {
                    var lit = ToAsciiDigits(t.Text);
                    if (string.IsNullOrWhiteSpace(lit))
                    {
                        // Whitespace in the pattern: accept any amount, including none.
                        var p = pos;
                        while (p < ascii.Length && char.IsWhiteSpace(ascii[p])) p++;
                        Walk(ti + 1, p, year, yearLen, month, day);
                    }
                    else if (pos + lit.Length <= ascii.Length
                             && string.Compare(ascii, pos, lit, 0, lit.Length, StringComparison.OrdinalIgnoreCase) == 0)
                    {
                        Walk(ti + 1, pos + lit.Length, year, yearLen, month, day);
                    }
                    return;
                }
                case PatternTokenKind.MonthName:
                {
                    foreach (var m in MonthsByNameLength)
                    {
                        foreach (var name in new[] { JalaliMonthNamesFa[m - 1], JalaliMonthNamesLatin[m - 1], JalaliMonthNamesLatinAbbr[m - 1] })
                        {
                            if (pos + name.Length <= ascii.Length
                                && string.Compare(ascii, pos, name, 0, name.Length, StringComparison.OrdinalIgnoreCase) == 0)
                                Walk(ti + 1, pos + name.Length, year, yearLen, m, day);
                        }
                    }
                    return;
                }
                case PatternTokenKind.DayName:
                {
                    // Weekday names carry no date information: skip the word.
                    var p = pos;
                    while (p < ascii.Length && char.IsLetter(ascii[p])) p++;
                    if (p > pos) Walk(ti + 1, p, year, yearLen, month, day);
                    return;
                }
                default:
                {
                    var runEnd = pos;
                    while (runEnd < ascii.Length && ascii[runEnd] is >= '0' and <= '9') runEnd++;
                    var available = runEnd - pos;
                    if (available == 0) return;

                    var adjacentNumeric = ti + 1 < tokens.Count && IsNumeric(tokens[ti + 1].Kind);
                    int[] widths = !adjacentNumeric
                        ? [available]
                        : t.Kind == PatternTokenKind.Year
                            ? [t.Width <= 2 ? 2 : 4]
                            : t.Width == 1 ? [1, 2] : [t.Width];

                    foreach (var w in widths)
                    {
                        if (w > available || w > 6) continue;
                        var value = int.Parse(ascii.AsSpan(pos, w), NumberStyles.None, CultureInfo.InvariantCulture);
                        switch (t.Kind)
                        {
                            case PatternTokenKind.Year:
                                Walk(ti + 1, pos + w, value, w, month, day);
                                break;
                            case PatternTokenKind.Month:
                                if (value is >= 1 and <= 12) Walk(ti + 1, pos + w, year, yearLen, value, day);
                                break;
                            default:
                                if (value is >= 1 and <= 31) Walk(ti + 1, pos + w, year, yearLen, month, value);
                                break;
                        }
                    }
                    return;
                }
            }
        }
    }

    /// <summary>Parses "Mehr 1403", "مهر ۱۴۰۳", "1403/07" or "07/1403" to the first of that Jalali month.</summary>
    public static bool TryParseJalaliMonth(string text, out DateOnly result)
    {
        result = default;
        if (string.IsNullOrWhiteSpace(text)) return false;

        var ascii = ToAsciiDigits(text.Trim());
        var runs = ExtractNumberRuns(ascii);
        var numbers = runs.Select(x => x.Value).ToList();
        var textualMonth = FindMonthName(ascii);

        int year, month;
        if (textualMonth > 0 && numbers.Count == 1)
        {
            year = numbers[0];
            month = textualMonth;
        }
        else if (numbers.Count == 2)
        {
            // The year is the wider part (1403/07, 07/1403, 0001/07).
            var firstIsYear = runs[0].Length != runs[1].Length
                ? runs[0].Length > runs[1].Length
                : numbers[0] > 12;
            (year, month) = firstIsYear ? (numbers[0], numbers[1]) : (numbers[1], numbers[0]);
        }
        else
        {
            return false;
        }

        return TryCreate(year, month, 1, out result);
    }

    /// <summary>Parses a Jalali year number to the first day of that year.</summary>
    public static bool TryParseJalaliYear(string text, out DateOnly result)
    {
        result = default;
        var numbers = ExtractNumbers(ToAsciiDigits(text.Trim()));
        return numbers.Count == 1 && TryCreate(numbers[0], 1, 1, out result);
    }

    private static bool TryCreate(int year, int month, int day, out DateOnly result)
    {
        result = default;
        if (year < 1 || month is < 1 or > 12 || day < 1) return false;
        try
        {
            if (day > Persian.GetDaysInMonth(year, month)) return false;
            result = DateOnly.FromDateTime(Persian.ToDateTime(year, month, day, 0, 0, 0, 0));
            return true;
        }
        catch (ArgumentOutOfRangeException)
        {
            return false;
        }
    }

    private static int DigitCount(string text) => text.Count(c => c is >= '0' and <= '9');

    /// <summary>The order of the numeric y/M/d tokens in <paramref name="pattern"/> and the
    /// digit width each takes when the parts are written without separators.</summary>
    private static string TokenOrder(string pattern, out List<int> widths, out List<string> literals)
    {
        widths = new List<int>(3);
        literals = new List<string>();
        var sb = new StringBuilder(3);
        for (var i = 0; i < pattern.Length; i++)
        {
            var ch = pattern[i];
            if (ch is '\'' or '"')
            {
                var close = pattern.IndexOf(ch, i + 1);
                if (close < 0) close = pattern.Length;
                literals.Add(pattern.Substring(i + 1, close - i - 1));
                i = close;
                continue;
            }
            if (ch == '\\') { i++; continue; }
            if (ch is 'y' or 'M' or 'd')
            {
                var run = 1;
                while (i + run < pattern.Length && pattern[i + run] == ch) run++;
                i += run - 1;
                // ddd/dddd are weekday names, not the day number.
                if (ch == 'd' && run >= 3) continue;
                if (sb.ToString().IndexOf(ch) < 0)
                {
                    sb.Append(ch);
                    widths.Add(ch == 'y' ? (run <= 2 ? 2 : 4) : 2);
                }
            }
        }
        return sb.ToString();
    }

    private static int FindMonthName(string text)
    {
        // Longest names first: "دی" (Dey) is a substring of "اردیبهشت" (Ordibehesht).
        foreach (var m in MonthsByNameLength)
        {
            if (text.Contains(JalaliMonthNamesFa[m - 1], StringComparison.Ordinal)
                || text.Contains(JalaliMonthNamesLatin[m - 1], StringComparison.OrdinalIgnoreCase))
                return m;
        }
        // Abbreviations last so "Tir"/"Dey" don't shadow longer names.
        for (var m = 1; m <= 12; m++)
        {
            if (System.Text.RegularExpressions.Regex.IsMatch(text, $@"\b{JalaliMonthNamesLatinAbbr[m - 1]}\b",
                    System.Text.RegularExpressions.RegexOptions.IgnoreCase))
                return m;
        }
        return 0;
    }

    private static List<int> ExtractNumbers(string ascii) =>
        ExtractNumberRuns(ascii).Select(x => x.Value).ToList();

    /// <summary>Each run of ASCII digits with its value and its digit count.</summary>
    private static List<(int Value, int Length)> ExtractNumberRuns(string ascii)
    {
        var result = new List<(int Value, int Length)>(3);
        var i = 0;
        while (i < ascii.Length)
        {
            if (ascii[i] is >= '0' and <= '9')
            {
                var start = i;
                while (i < ascii.Length && ascii[i] is >= '0' and <= '9') i++;
                if (i - start > 6) return [];
                result.Add((int.Parse(ascii.AsSpan(start, i - start), NumberStyles.None, CultureInfo.InvariantCulture), i - start));
            }
            else
            {
                i++;
            }
        }
        return result;
    }

    /// <summary>Maps Persian (۰–۹), Arabic-Indic (٠–٩) and any other Unicode decimal digits to ASCII.</summary>
    internal static string ToAsciiDigits(string text)
    {
        var sb = new StringBuilder(text.Length);
        foreach (var ch in text)
        {
            var value = CharUnicodeInfo.GetDecimalDigitValue(ch);
            sb.Append(value >= 0 ? (char)('0' + value) : ch);
        }
        return sb.ToString();
    }
}
